import json,sys
table=json.load(open(sys.argv[1]));window=sys.argv[2];kind=sys.argv[3];c=json.load(open(table['sources']['stock']['contract_file']))['vp_contract'];errors=[]
assert set(table['modes'])=={'14','15','19','21','24','28','29'}
for m,row in table['modes'].items():
 v=row['lite'] if window=='common1s' else row['lite']['full_retained_trace']
 if kind=='target':
  if v['primary_body_us']['max']>1800:errors.append(f'{m} max {v["primary_body_us"]["max"]}>1800')
 elif kind=='hard_ceiling':
  if v['primary_body_us']['max']>c['effect_code_hard_ceiling_us']:errors.append(f'{m} max {v["primary_body_us"]["max"]}>{c["effect_code_hard_ceiling_us"]}')
 else:
  d=v['cadence'];assert d is not None
  vals={'frame_start_delta_p99_max_us':d['frame_start_delta_us']['p99'],'arithmetic_mean_max_us':d['frame_start_delta_us']['mean'],'max_consecutive_misses':d['max_consecutive_misses'],'recovery_frames_max':d['recovery_frames_max']}
  errors.extend(f'{m} {k} {x}>{c["admission"][k]}' for k,x in vals.items() if x>c['admission'][k])
  if d['recovery_right_censored']:errors.append(f'{m} right-censored recovery')
print(json.dumps({'window':window,'kind':kind,'errors':errors}))
sys.exit(bool(errors))

