import json,sys
p,kind=sys.argv[1:];r=json.load(open(p));contract=json.load(open(r['contract_file']))['vp_contract'];expected={'24'} if r['tag']=='lite-forge3' else {'14','15','19','21','24','28','29'};errors=[]
if not expected<=set(r['modes']):errors.append('missing modes')
