 v=r['modes'][m]
 if kind=='coverage':
  for key in ['total_exclusive_scoped_share','minimum_call_scoped_share']:
   if v['coverage'][key] is None or not .90<=v['coverage'][key]<=1:errors.append(f'{m} {key} {v["coverage"][key]}')
 elif kind=='cadence':
  d=v['cadence']
  if d is None:errors.append(f'{m} cadence unverified');continue
  values={'frame_start_delta_p99_max_us':d['frame_start_delta_us']['p99'],'arithmetic_mean_max_us':d['frame_start_delta_us']['mean'],'max_consecutive_misses':d['max_consecutive_misses'],'recovery_frames_max':d['recovery_frames_max']}
  errors.extend(f'{m} {k} {x}>{contract["admission"][k]}' for k,x in values.items() if x>contract['admission'][k])
  if d['recovery_right_censored']:errors.append(f'{m} recovery right censored')
 else:
  limit=1800 if kind=='lite_target' else contract['effect_code_hard_ceiling_us']
  if v['primary_body_us']['max']>limit:errors.append(f'{m} max {v["primary_body_us"]["max"]}>{limit}')
print(json.dumps({'kind':kind,'tag':r['tag'],'errors':errors}))
sys.exit(bool(errors))

